import sys
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
import os

def log_error(log_file, message):
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
    with open(log_file, 'a') as f:
        f.write(f"{timestamp} ERROR: {message}\n")

def log_info(log_file, message, item_count=None):
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
    with open(log_file, 'a') as f:
        if item_count is not None:
            f.write(f"{timestamp} INFO: rendered {item_count} items\n")
        else:
            f.write(f"{timestamp} INFO: {message}\n")

def parse_xml(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        if root.tag != 'report':
            return None
        items = []
        for item in root.findall('item'):
            if 'name' not in item.attrib or 'value' not in item.attrib:
                return None
            items.append((item.attrib['name'], item.attrib['value']))
        return items
    except (ET.ParseError, IOError):
        return None

def generate_html(title, items, output_file):
    html_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>{title}</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }}
        tr:nth-child(even) {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <h1>{title}</h1>
    <table>
        <tr>
            <th>Name</th>
            <th>Value</th>
        </tr>
"""
    for name, value in items:
        html_content += f"""        <tr>
            <td>{name}</td>
            <td>{value}</td>
        </tr>
"""
    html_content += """
    </table>
</body>
</html>
"""
    with open(output_file, 'w') as f:
        f.write(html_content)

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python render_report.py config.xml report.html app.log")
        sys.exit(1)

    xml_file = sys.argv[1]
    output_file = sys.argv[2]
    log_file = sys.argv[3]

    log_info(log_file, "starting")

    items = parse_xml(xml_file)
    if items is None:
        log_error(log_file, "invalid config")
        sys.exit(1)

    log_info(log_file, "", len(items))
    generate_html(sys.argv[1].split('/')[-1].split('.')[0], items, output_file)
    sys.exit(0)
